messages.content:
Tool response:
Tool: cancel_subscription
Description: Cancel a user's subscription with a reason
Parameters:
    {
      "type": "object",
      "properties": {
        "subscription_id": {
          "type": "integer",
          "description": "Internal ID of the subscription to cancel",
          "title": "Subscription Id"
        },
        "reason": {
          "type": "string",
          "title": "Reason",
          "description": "Reason for cancelling the subscription"
        }
      },
      "required": [
        "subscription_id",
        "reason"
      ]
    }
